/* ПОМОДОРО. Образец ЖИВОГО ПОТОКА: таймер тикает между вызовами, переменные
   живут, пока открыта панель. Раньше такое было невозможно — поток закрывался
   после каждого щелчка, и таймеру негде было жить.

   Настройки снимаются при пуске и хранятся рядом с таймером: в тике «параметры()»
   спрашивать не у кого — вызова нет, есть только таймер. */

let тик = null;          // ссылка на таймер
let осталось = 0;        // секунд до конца этапа
let идёт = false;
let этап = 'работа';     // работа | короткий | длинный
let сделано = 0;         // помидоров завершено
let начало = null;       // когда начался нынешний помидор
let нст = {работа: 25, короткий: 5, длинный: 15, через: 4, сами: false, вЛист: false, лист: 'Помодоро', задача: ''};

const ДВА = ч => (ч < 10 ? '0' : '') + ч;
const времяСтрокой = с => ДВА(Math.floor(с / 60)) + ':' + ДВА(с % 60);
const ПОРУССКИ = {работа: 'работа', короткий: 'короткий перерыв', длинный: 'длинный перерыв'};

function снять(){
  const п = параметры({});
  нст = {
    работа: Math.max(1, +п.работа || 25), короткий: Math.max(1, +п.короткий || 5),
    длинный: Math.max(1, +п.длинный || 15), через: Math.max(1, +п.через || 4),
    сами: !!п.сами, вЛист: !!п.вЛист, лист: String(п.лист || 'Помодоро'), задача: String(п.задача || ''),
  };
}
const длительность = э => (э === 'работа' ? нст.работа : э === 'короткий' ? нст.короткий : нст.длинный) * 60;

function показать(){
  const всего = длительность(этап) || 1;
  панель.поле('часы', времяСтрокой(осталось) + '  ·  ' + ПОРУССКИ[этап] + (идёт ? '' : ' (пауза)'));
  панель.поле('ход', Math.max(0, Math.min(1, 1 - осталось / всего)));
  панель.поле('сделано', String(сделано));
}

function Пуск(){
  снять();
  if(идёт) return;
  if(!осталось) осталось = длительность(этап);
  идёт = true;
  if(!начало) начало = сейчас();
  if(!тик) тик = setInterval(шаг, 1000);
  показать();
  панель.сообщение('Пошли: ' + ПОРУССКИ[этап] + ', ' + времяСтрокой(осталось));
}

function Пауза(){ идёт = false; показать(); панель.сообщение('Пауза на ' + времяСтрокой(осталось)); }

function Сброс(){
  снять();
  идёт = false; этап = 'работа'; осталось = длительность('работа'); начало = null;
  показать();
  панель.сообщение('Сброшено');
}

async function шаг(){
  if(!идёт) return;
  осталось--;
  if(осталось > 0){ показать(); return; }
  const кончился = этап;
  if(этап === 'работа'){
    сделано++;
    if(нст.вЛист) записать(кончился);
    начало = null;
    этап = (сделано % нст.через === 0) ? 'длинный' : 'короткий';
  } else этап = 'работа';
  осталось = длительность(этап);
  идёт = нст.сами;
  показать();
  await диалог.сообщение(кончился === 'работа'
    ? 'Помидор готов (' + сделано + '). Дальше — ' + ПОРУССКИ[этап] + '.'
    : 'Перерыв кончился. Дальше — работа.');
}

/* Строка учёта на отдельный лист. Лист должен существовать: заводить листы
   за спиной у человека плагину не положено — скажем, если его нет. */
function записать(этап2){
  if(книга.листы.map(и => String(и).toLowerCase()).indexOf(нст.лист.toLowerCase()) < 0){
    панель.сообщение('Листа «' + нст.лист + '» нет — заведите его, и учёт пойдёт туда');
    return;
  }
  const л = лист(нст.лист);
  let строка = (л.строк || 0) + 1;
  if(строка === 1){ л.диапазон('A1:D1').записать([['Начало', 'Конец', 'Этап', 'Задача']]); строка = 2; }
  л.диапазон('A' + строка + ':D' + строка).записать([[начало || сейчас(), сейчас(), ПОРУССКИ[этап2], нст.задача]]);
}

function сейчас(){ const д = new Date(); return ДВА(д.getHours()) + ':' + ДВА(д.getMinutes()) + ':' + ДВА(д.getSeconds()); }

function Старт(){
  снять();
  if(!осталось) осталось = длительность('работа');
  показать();
  панель.сообщение('Помодоро: работа, короткий перерыв, после четвёртого — длинный. Таймер живёт, пока открыта эта панель.');
}

/* Кнопка ленты: пуск и пауза одной кнопкой */
function Качели(){ if(идёт) Пауза(); else Пуск(); }
